package com.ethk3.novaonepro.strategyv2;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;
/** Causal old/current comparisons are separate preregistered research, not relabeled formal outcomes. */
public final class ModelReplayStudyR30R1 {
 private ModelReplayStudyR30R1(){}private static final java.util.concurrent.atomic.AtomicLong invalidPreviousReferences=new java.util.concurrent.atomic.AtomicLong();private static volatile String previousFailureType;public static final String VERSION="MODEL_PREVIOUS_VS_CURRENT_PREDECLARED1";
 static ModelSurfaceProviderR30.FrozenModelRef previous(SQLiteDatabase db,ModelSurfaceProviderR30.FrozenModelRef current,long target,long now){try(Cursor q=db.rawQuery("SELECT model_hash,weights,trained_through_ordinal,available_at FROM r30_model_artifact WHERE feature_abi=? AND model_hash<>? AND trained_through_ordinal<? AND available_at<=? ORDER BY available_at DESC,model_hash LIMIT 1",new String[]{AtomNetSessionR30.ABI,current.modelHash,String.valueOf(target),String.valueOf(Math.min(now,current.availableAt))})){if(!q.moveToFirst())return null;try{return ModelSurfaceProviderR30.FrozenModelRef.archived(q.getString(0),q.getBlob(1),q.getLong(2),q.getLong(3));}catch(ModelSurfaceProviderR30.Blocked|IllegalArgumentException invalid){invalidPreviousReferences.incrementAndGet();previousFailureType=invalid.getClass().getSimpleName();return null;}}}
 public static Map<String,Object> freeze(OnlineResearchWindowR30R1.Window window,ModelSurfaceProviderR30.Pit pit,ModelSurfaceProviderR30.Surface current,ModelSurfaceProviderR30.FrozenModelRef previous){window.require(pit.targetOrdinal,pit.preparedAt);if(previous.modelHash.equals(current.modelHash))throw new IllegalArgumentException("MODEL_PAIR_NOT_DISTINCT");ModelSurfaceProviderR30.Surface older=ModelSurfaceProviderR30.predict(pit,previous);if(!older.historyHash.equals(current.historyHash)||older.targetOrdinal!=current.targetOrdinal||older.position!=current.position||older.frozenAt!=current.frozenAt)throw new IllegalStateException("MODEL_PAIR_NOT_SAME_PREDRAW");Map<String,Object> p=new LinkedHashMap<>();p.put("version",VERSION);p.put("role","ONLINE_RESEARCH");p.put("windowId",window.id);p.put("windowRegisteredAt",window.registeredAt);p.put("targetOrdinal",pit.targetOrdinal);p.put("targetIssue",com.ethk3.novaonepro.TargetIssueResolver.fromSequenceOrdinalSU1(pit.targetOrdinal));p.put("position",pit.position);p.put("historyHash",current.historyHash);p.put("currentModelHash",current.modelHash);p.put("previousModelHash",older.modelHash);p.put("currentProbabilityHash",current.probabilityHash);p.put("previousProbabilityHash",older.probabilityHash);p.put("current",current.probabilities());p.put("previous",older.probabilities());p.put("currentThrough",current.trainedThroughOrdinal);p.put("previousThrough",older.trainedThroughOrdinal);p.put("currentAvailableAt",current.modelAvailableAt);p.put("previousAvailableAt",older.modelAvailableAt);p.put("frozenAt",current.frozenAt);p.put("deadlineAt",current.deadlineAt);p.put("replayConfiguration","ORIGINAL_63_REPLAY_SAMPLES_NO_RESET");p.put("receiptHash",StatsR27.sha256(JsonR27.write(p)));return p;}
 public static void append(ResearchWriteQueueR27.Batch b,OnlineResearchWindowR30R1.Window window,ModelSurfaceProviderR30.Pit pit,ModelSurfaceProviderR30.Surface current,ModelSurfaceProviderR30.FrozenModelRef previous){if(window==null||previous==null)return;Map<String,Object> p=freeze(window,pit,current,previous);String key="MODEL_PAIR_FROZEN:"+pit.targetOrdinal+":P"+pit.position;b.add("INSERT OR IGNORE INTO r30r1_research_measure VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",window.id,key,"MODEL_PAIR_FROZEN",current.modelHash,VERSION,pit.targetOrdinal,pit.targetOrdinal,0,null,null,null,JsonR27.write(p));}
 static double[] probabilities(Object raw){if(!(raw instanceof List)||((List<?>)raw).size()!=10)throw new IllegalArgumentException("MODEL_PAIR_PROBABILITY_SHAPE");double[] p=new double[10];for(int i=0;i<10;i++)p[i]=((Number)((List<?>)raw).get(i)).doubleValue();return p;}
 @SuppressWarnings("unchecked") static Map<String,Object> verified(String json){Map<String,Object> p=(Map<String,Object>)JsonR27.parse(json);Object hash=p.remove("receiptHash");if(!StatsR27.sha256(JsonR27.write(p)).equals(hash))throw new IllegalStateException("MODEL_PAIR_RECEIPT_HASH");p.put("receiptHash",hash);if(!VERSION.equals(p.get("version"))||!"ONLINE_RESEARCH".equals(p.get("role")))throw new IllegalStateException("MODEL_PAIR_ROLE");long target=((Number)p.get("targetOrdinal")).longValue(),frozen=((Number)p.get("frozenAt")).longValue(),deadline=((Number)p.get("deadlineAt")).longValue();if(((Number)p.get("windowRegisteredAt")).longValue()>=frozen||((Number)p.get("currentThrough")).longValue()>=target||((Number)p.get("previousThrough")).longValue()>=target||((Number)p.get("currentAvailableAt")).longValue()>frozen||((Number)p.get("previousAvailableAt")).longValue()>frozen||deadline-frozen<LiveShadowsR27.FREEZE_MARGIN_MS)throw new IllegalStateException("MODEL_PAIR_PIT");if(!StatsR27.sha256(StoreR27.pack(probabilities(p.get("current")))).equals(p.get("currentProbabilityHash"))||!StatsR27.sha256(StoreR27.pack(probabilities(p.get("previous")))).equals(p.get("previousProbabilityHash")))throw new IllegalStateException("MODEL_PAIR_PROBABILITY_HASH");return p;}
 static boolean settle(ResearchPoolR27.Worker w)throws Exception{
  final long observedRevision=SchemaR27.liveSourceRevision(w.ro);if(observedRevision<0)return false;String run=null,issue=null;long ordinal=-1;int[] actual=new int[10];String sql="SELECT m.run_id,m.from_ordinal,d.issue,d.n1,d.n2,d.n3,d.n4,d.n5,d.n6,d.n7,d.n8,d.n9,d.n10 FROM r30r1_research_measure m JOIN r30r1_analysis_run r ON r.run_id=m.run_id JOIN draws d ON "+ResearchInputPinR30R1.ordinal("d")+"=m.from_ordinal WHERE m.kind='MODEL_PAIR_FROZEN' AND r.role='ONLINE_RESEARCH' AND r.status='ONLINE_MODEL_ROLE_REGISTERED' AND NOT EXISTS(SELECT 1 FROM r30r1_research_measure invalid WHERE invalid.run_id=r.run_id AND invalid.kind='INPUT_INVALIDATION') AND d.dirty=0 AND NOT EXISTS(SELECT 1 FROM r30r1_research_measure s WHERE s.run_id=m.run_id AND s.measure_key='MODEL_PAIR_SETTLED:'||m.from_ordinal) GROUP BY m.run_id,m.from_ordinal ORDER BY m.from_ordinal LIMIT 1";try(Cursor q=w.ro.rawQuery(sql,null)){if(q.moveToFirst()){run=q.getString(0);ordinal=q.getLong(1);issue=q.getString(2);for(int i=0;i<10;i++)actual[i]=q.getInt(i+3);}}if(run==null)return false;if(!ReplayDatasetR27.legal(actual))throw new IllegalStateException("MODEL_PAIR_CANONICAL_LABEL");
  List<Object> details=new ArrayList<>();Set<Integer> positions=new HashSet<>();double oldLoss=0,newLoss=0;String oldModel=null,newModel=null;try(Cursor q=w.ro.rawQuery("SELECT payload_json FROM r30r1_research_measure WHERE run_id=? AND kind='MODEL_PAIR_FROZEN' AND from_ordinal=? ORDER BY measure_key",new String[]{run,String.valueOf(ordinal)})){while(q.moveToNext()){Map<String,Object> p=verified(q.getString(0));int pos=((Number)p.get("position")).intValue();if(pos<1||pos>10||!positions.add(pos)||ordinal!=((Number)p.get("targetOrdinal")).longValue()||!run.equals(p.get("windowId")))throw new IllegalStateException("MODEL_PAIR_TARGET_OR_POSITION");if(oldModel==null){oldModel=(String)p.get("previousModelHash");newModel=(String)p.get("currentModelHash");}if(!oldModel.equals(p.get("previousModelHash"))||!newModel.equals(p.get("currentModelHash")))throw new IllegalStateException("MODEL_PAIR_MIXED_MODELS");double a=FusionStudyR30R1.loss(probabilities(p.get("previous")),actual[pos-1]),b=FusionStudyR30R1.loss(probabilities(p.get("current")),actual[pos-1]);if(!Double.isFinite(a)||!Double.isFinite(b))throw new IllegalStateException("MODEL_PAIR_LOSS");oldLoss+=a;newLoss+=b;Map<String,Object> d=new LinkedHashMap<>();d.put("position",pos);d.put("receiptHash",p.get("receiptHash"));d.put("oldLoss",a);d.put("newLoss",b);details.add(d);}}
  if(positions.size()!=10)return false;Map<String,Object> payload=new LinkedHashMap<>();payload.put("version",VERSION);payload.put("role","ONLINE_RESEARCH");payload.put("windowId",run);payload.put("targetOrdinal",ordinal);payload.put("targetIssue",issue);payload.put("oldModelHash",oldModel);payload.put("newModelHash",newModel);payload.put("previousLoss",oldLoss/10);payload.put("currentLoss",newLoss/10);payload.put("calendarIssues",1);payload.put("positionSamples",10);payload.put("sourceReceipts",details);payload.put("naturalCertificate",false);if(observedRevision!=SchemaR27.liveSourceRevision(w.ro))return false;final String windowRun=run;ResearchWriteQueueR27.Batch b=new ResearchWriteQueueR27.Batch();b.guardBefore(db->{if(SchemaR27.liveSourceRevision(db)!=observedRevision||!SchemaR27.liveSourceTriggersValid(db))return -1;try(Cursor invalid=db.rawQuery("SELECT 1 FROM r30r1_research_measure WHERE run_id=? AND kind='INPUT_INVALIDATION' LIMIT 1",new String[]{windowRun})){return invalid.moveToFirst()?-1:0;}});appendTemporalAudit(w.ro,b,run,ordinal,details);b.add("INSERT OR IGNORE INTO r30r1_research_measure VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",run,"MODEL_PAIR_SETTLED:"+ordinal,"MODEL_PAIR_SETTLED",newModel,VERSION,ordinal,ordinal,1,(oldLoss-newLoss)/10,null,null,JsonR27.write(payload));try{RuntimeR27.submit(w,"ONLINE_MODEL_PAIR_SETTLEMENT",b);}catch(IllegalStateException changed){if(QualificationInboxR29.precondition(changed))return false;throw changed;}return true;
 }
 @SuppressWarnings("unchecked") static void appendTemporalAudit(SQLiteDatabase db,ResearchWriteQueueR27.Batch b,String window,long ordinal,List<Object> frozenSources){try(Cursor q=db.rawQuery("SELECT r.run_id,r.summary_json,r.contract_hash FROM r30r1_research_measure m JOIN r30r1_analysis_run r ON r.run_id=m.run_id WHERE m.kind='MATRIX_TEMPORAL_PRECEDENCE' AND r.role='ONLINE_RESEARCH' AND r.status='COMMITTED' AND r.from_ordinal=? AND r.source_commit=? ORDER BY r.recorded_at DESC LIMIT 1",new String[]{String.valueOf(ordinal-1),com.ethk3.novaonepro.BuildConfig.SOURCE_COMMIT_R26})){if(!q.moveToFirst()||!ResearchStoreR30R1.currentSource(com.ethk3.novaonepro.BuildConfig.SOURCE_COMMIT_R26,q.getString(1)))return;Map<String,Object> source=(Map<String,Object>)JsonR27.parse(q.getString(1));Object raw=source.get("frame");if(!(raw instanceof Map)||!StatsR27.sha256(JsonR27.write(raw)).equals(q.getString(2)))throw new IllegalStateException("TEMPORAL_MATRIX_SOURCE_HASH");Map<String,Object> matrix=(Map<String,Object>)raw;Map<?,?> d=(Map<?,?>)matrix.get("details");if(!window.equals(d.get("sourceRun")))return;Map<String,Object> original=verified(JsonR27.write(d.get("originalReceipt")));boolean matched=false;for(Object row:frozenSources)if(((Map<?,?>)row).get("receiptHash").equals(original.get("receiptHash")))matched=true;if(!matched)return;List<?> values=(List<?>)matrix.get("values");for(Object row:values)for(Object value:(List<?>)row)if(!(value instanceof Number)||((Number)value).doubleValue()<0)throw new IllegalStateException("TEMPORAL_MATRIX_NEGATIVE_MARGIN");Map<String,Object> receipt=new LinkedHashMap<>();receipt.put("windowId",window);receipt.put("targetOrdinal",ordinal);receipt.put("originalFrozenReceiptHash",original.get("receiptHash"));receipt.put("matrixSourceRun",q.getString(0));receipt.put("action","CHECK_ACTUAL_MODEL_AVAILABILITY_AND_FREEZE_MARGIN_BEFORE_JOINING_RESEARCH_LABEL");receipt.put("authority","ORIGINAL_PIT_GUARD_UNCHANGED_NO_REAL_ISSUANCE");b.add("INSERT OR IGNORE INTO r30r1_research_measure VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",q.getString(0),"TEMPORAL_AUDIT:"+window+":"+ordinal,"MODEL_TEMPORAL_RESEARCH_AUDIT",(String)original.get("currentModelHash"),VERSION,ordinal-1,ordinal,0,null,null,null,JsonR27.write(receipt));}}
 public static String replayPolicy(Map<String,Object> evidence,String current){if(!VERSION.equals(evidence.get("protocol"))||!"ONLINE_RESEARCH".equals(evidence.get("role"))||!Boolean.FALSE.equals(evidence.get("formalTablesRead"))||!"DESCRIPTIVE_ONLINE_RESEARCH_ONLY".equals(evidence.get("status"))||!(evidence.get("completeBlocks") instanceof Number)||((Number)evidence.get("completeBlocks")).intValue()<4||!(evidence.get("calendarIssues") instanceof Number)||((Number)evidence.get("calendarIssues")).intValue()<200||!(evidence.get("missingObservedIssues") instanceof Number)||((Number)evidence.get("missingObservedIssues")).longValue()!=0||!(evidence.get("upper95") instanceof Number)||(!Double.isFinite(((Number)evidence.get("upper95")).doubleValue())||((Number)evidence.get("upper95")).doubleValue()>=0))return current;return "OLD48_RECENT15";}
 static final class ReplayDecision {final String run,fromPolicy,toPolicy;final long from,through;ReplayDecision(String run,String a,String b,long from,long through){this.run=run;fromPolicy=a;toPolicy=b;this.from=from;this.through=through;}}
 static ReplayDecision allocateReplay(SQLiteDatabase db,AtomNetSessionR30 state,ResearchWriteQueueR27.Batch b){if(!state.ready()||state.nextPosition!=1||state.trainer.onlineSteps%(10L*64)!=0)return null;Map<String,Object> evidence=summary(db);String proposed=replayPolicy(evidence,state.replayPolicy);if(proposed.equals(state.replayPolicy)||!state.datasetHash.equals(evidence.get("datasetHash")))return null;String run=ResearchContractR30R1.sha(String.valueOf(evidence.get("windowId")));if(run.equals(state.replayEvidenceRun))return null;long from=((Number)evidence.get("fromOrdinal")).longValue(),through=((Number)evidence.get("throughOrdinal")).longValue();ReplayDecision decision=new ReplayDecision(run,state.replayPolicy,proposed,from,through);b.guardBefore(tx->{try(Cursor q=tx.rawQuery("SELECT 1 FROM r30r1_analysis_run r WHERE r.run_id=? AND r.role='ONLINE_RESEARCH' AND r.status='ONLINE_MODEL_ROLE_REGISTERED' AND r.dataset_hash=? AND NOT EXISTS(SELECT 1 FROM r30r1_research_measure invalid WHERE invalid.run_id=r.run_id AND invalid.kind='INPUT_INVALIDATION')",new String[]{run,state.datasetHash})){return q.moveToFirst()?0:-1;}});state.replayPolicy=proposed;state.replayEvidenceRun=run;state.replayPolicyChanges++;return decision;}
 static void recordReplayDecision(ResearchWriteQueueR27.Batch b,AtomNetSessionR30 state,ReplayDecision decision,String checkpoint){if(decision==null)return;Map<String,Object> p=new LinkedHashMap<>();p.put("learningProtocol",AtomNetSessionR30.LEARNING_PROTOCOL);p.put("role","ONLINE_RESEARCH");p.put("fromPolicy",decision.fromPolicy);p.put("toPolicy",decision.toPolicy);p.put("actualCheckpointHash",checkpoint);p.put("primaryNewSamplesPerStep",1);p.put("maximumReplaySamplesPerStep",63);p.put("maximumBatchSize",64);p.put("modelOrOptimizerReset",false);p.put("evidenceIsProofOfReplayBenefit",false);p.put("futureIndependentConfirmationRequired",true);b.add("INSERT OR IGNORE INTO r30r1_research_measure VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",decision.run,"REPLAY_ALLOCATION:"+checkpoint,"NEURAL_REPLAY_RESEARCH_ALLOCATION",checkpoint,"ACTUAL_LEARNER_CHECKPOINT_SAME_TRANSACTION",decision.from,decision.through,0,null,null,null,JsonR27.write(p));}
 public static Map<String,Object> summary(SQLiteDatabase db){Map<String,Object> out=new LinkedHashMap<>();out.put("protocol",VERSION);out.put("role","ONLINE_RESEARCH");out.put("formalTablesRead",false);out.put("inputDriftIsPerformanceDegradation",false);out.put("modelReset",false);out.put("invalidPreviousReferencesObservedInProcess",invalidPreviousReferences.get());out.put("previousReferenceFailureType",previousFailureType);String run=null;long from=0,to=0;try(Cursor q=db.rawQuery("SELECT r.run_id,r.from_ordinal,r.through_ordinal,r.dataset_hash FROM r30r1_analysis_run r WHERE r.role='ONLINE_RESEARCH' AND r.status='ONLINE_MODEL_ROLE_REGISTERED' AND NOT EXISTS(SELECT 1 FROM r30r1_research_measure invalid WHERE invalid.run_id=r.run_id AND invalid.kind='INPUT_INVALIDATION') AND EXISTS(SELECT 1 FROM r30r1_research_measure m WHERE m.run_id=r.run_id AND m.kind='MODEL_PAIR_SETTLED') ORDER BY r.recorded_at DESC LIMIT 1",null)){if(q.moveToFirst()){run=q.getString(0);from=q.getLong(1);to=q.getLong(2);out.put("datasetHash",q.getString(3));}}if(run==null){out.put("status","INSUFFICIENT_PREREGISTERED_OLD_NEW_MODEL_PAIRS");return out;}out.put("registeredThroughOrdinal",to);try(Cursor latest=db.rawQuery("SELECT max(from_ordinal) FROM r30r1_research_measure WHERE run_id=? AND kind='MODEL_PAIR_SETTLED'",new String[]{run})){if(latest.moveToFirst()&&!latest.isNull(0))to=Math.min(to,latest.getLong(0));}out.put("fromOrdinal",from);out.put("throughOrdinal",to);ResearchGainR30R1 g=new ResearchGainR30R1(from,to,64,4,200);int n=0;try(Cursor q=db.rawQuery("SELECT from_ordinal,payload_json FROM r30r1_research_measure WHERE run_id=? AND kind='MODEL_PAIR_SETTLED' ORDER BY from_ordinal",new String[]{run})){while(q.moveToNext()){if(q.getLong(0)>to)continue;@SuppressWarnings("unchecked")Map<String,Object> p=(Map<String,Object>)JsonR27.parse(q.getString(1));g.add(q.getLong(0),((Number)p.get("previousLoss")).doubleValue(),((Number)p.get("currentLoss")).doubleValue());n++;}}ResearchGainR30R1.Estimate e=g.estimate();out.put("windowId",run);out.put("calendarIssues",n);out.put("positionSamples",10L*n);out.put("meanGainCurrentVsPrevious",e.meanBlockGain);out.put("lower95",e.lower95);out.put("upper95",e.upper95);out.put("blocks",g.blocks());out.put("completeBlocks",e.completeBlocks);out.put("missingObservedIssues",e.missingIssues);out.put("excludedTailIssues",e.excludedTailIssues);out.put("status",e.supported()?"DESCRIPTIVE_ONLINE_RESEARCH_ONLY":"INSUFFICIENT_COMPLETE_FIXED_BLOCKS");out.put("action",e.supported()&&e.upper95<0?"PROPOSE_OLD48_RECENT15_WITHIN_ORIGINAL_64_BATCH_RESEARCH_RULE_NO_MODEL_OR_QUALIFICATION_RESET":"KEEP_ORIGINAL_63_REPLAY_SAMPLES");return out;}
}
